D={
70050:("Partes do corpo: my + parte","Para o corpo: **my mouth, my arm, my leg**. Dor: **I have a headache.** Para pedir: **Open your mouth.**",[("{{Open}} your mouth, please.","Abra a boca, por favor."),("{{My}} arm is strong.","Meu braço é forte."),("I {{have a headache}}.","Estou com dor de cabeça."),("Her neck hurts.","O pescoço dela dói.")],"“Estou com dor de cabeça”:",["I have a headache.","I am headache.","I do headache."],0,"have a headache."),
910012:("Go home, go to work","**Go home** (sem to). **Go to** + lugar: *go to work, go to school, go to the pool.* Mas **home** não pede *to*.",[("I {{go home}} at six.","Vou para casa às seis."),("We {{go to the}} aquarium.","Vamos ao aquário."),("She {{goes to work}}.","Ela vai ao trabalho."),("They go shopping.","Eles vão fazer compras.")],"Qual está certa?",["go to home","go home","go at home"],1,"Home não leva to."),
10166:("Dias da semana","Dias da semana começam com **maiúscula** e usam **on**: **on Monday**. *We meet on Monday.* Mês usa **in**: *in March*.",[("We meet {{on Monday}}.","Nos encontramos na segunda."),("The class is {{on Wednesday}}.","A aula é na quarta."),("My birthday is {{in}} March.","Meu aniversário é em março."),("Look at the calendar.","Olhe o calendário.")],"Qual preposição com dias?",["in","on","at"],1,"on + dia."),
70051:("Rotina da manhã","Rotina no presente: **I brush my teeth / She brushes her teeth.** Com **he, she, it** o verbo ganha **-s**.",[("I {{brush}} my teeth.","Escovo os dentes."),("She {{brushes}} her hair.","Ela penteia o cabelo."),("He {{takes}} a shower.","Ele toma banho."),("I put on my slippers.","Calço meus chinelos.")],"Complete: “He ___ a shower.”",["take","takes","taking"],1,"he + verbo-s."),
30026:("Pedir no mercado","No mercado: **Where are the tomatoes?** **Where is the cereal?** Resposta: **It's on the left / on the right.**",[("{{Where are}} the tomatoes?","Onde estão os tomates?"),("They're {{on the left}}.","Estão à esquerda."),("{{Where is}} the cereal?","Onde está o cereal?"),("It's {{on the right}}.","Está à direita.")],"O que significa on the left?",["à esquerda","à direita","em frente"],0,"Left = esquerda."),
70052:("Near, far, next to","**Near** = perto. **Far** = longe. **Next to** = ao lado de. *The tray is next to the cream.*",[("The cafe is {{near}}.","O café é perto."),("The straw is {{next to}} the cup.","O canudo está ao lado do copo."),("It isn't {{far}}.","Não é longe."),("A croissant, please.","Um croissant, por favor.")],"“Ao lado de”:",["next to","far from","under"],0,"Next to = ao lado."),
10167:("Pedir ajuda: Can you…?","Para pedir: **Can you open the trunk?** Resposta: **Sure.** / **Sorry, I can't.** **Can** não muda com a pessoa.",[("{{Can you}} open the trunk?","Você pode abrir o porta-malas?"),("{{Sure}}!","Claro!"),("{{Can you}} check the tires?","Pode verificar os pneus?"),("{{Sorry, I can't}}.","Desculpe, não posso.")],"Como pedir educadamente que abram a janela?",["Can you open the window?","You can open window?","Can open you window?"],0,"Can you + verbo?"),
70053:("Viajar de…","Para meios de transporte: **by** + meio. *by bicycle, by ferry, by ship.* Exceção: **on foot**.",[("I go {{by bicycle}}.","Vou de bicicleta."),("We travel {{by ferry}}.","Viajamos de balsa."),("She goes {{by ship}}.","Ela vai de navio."),("He goes {{on foot}}.","Ele vai a pé.")],"“Ir de moto”:",["by motorcycle","in motorcycle","with motorcycle"],0,"by + meio."),
30027:("Datas e meses","Meses têm **maiúscula**: *January, March, July.* Para data: **What's the date?** — *It's October tenth.*",[("{{What's the date}}?","Que dia é hoje?"),("It's {{October}} tenth.","É dez de outubro."),("My birthday is in {{July}}.","Meu aniversário é em julho."),("The year starts in {{January}}.","O ano começa em janeiro.")],"Como perguntar a data?",["What's the date?","Which day today?","What date is?"],0,"What's the date?"),
70054:("Hobbies: I like + -ing","Para hobbies: **I like cooking. I love drawing.** Depois de *like/love* o verbo vai com **-ing**.",[("I {{like cooking}}.","Gosto de cozinhar."),("She {{loves drawing}}.","Ela adora desenhar."),("We {{like fishing}}.","Gostamos de pescar."),("I play chess.","Jogo xadrez.")],"Complete: “I like ___.”",["swim","swimming","to swimming"],1,"like + -ing."),
910013:("Wake up, get up","**Wake up** = acordar. **Get up** = levantar. **Get dressed** = vestir-se. São blocos fixos da manhã.",[("I {{wake up}} at six.","Acordo às seis."),("Then I {{get up}}.","Depois me levanto."),("I {{get dressed}}.","Eu me visto."),("The rooster sings!","O galo canta!")],"“Levantar da cama”:",["get up","wake down","put up"],0,"Get up."),
10168:("This size, that size","Para pedir tamanho: **Do you have this in a larger size?** **Is this my size?** Resposta: **Yes, it is.**",[("{{Is this}} my size?","Este é o meu tamanho?"),("{{Do you have}} a larger size?","Você tem um tamanho maior?"),("Yes, we do.","Sim, temos."),("A button is missing.","Está faltando um botão.")],"Como pedir um tamanho maior?",["Do you have a larger size?","You have large?","Larger you?"],0,"Do you have…?"),
70055:("Ter em casa: there is","Para falar da casa: **There is a sofa. There are two curtains.** Singular: **there is**. Plural: **there are**.",[("{{There is}} a sofa.","Há um sofá."),("{{There are}} two curtains.","Há duas cortinas."),("{{There is}} a fridge.","Há uma geladeira."),("{{There are}} books on the shelf.","Há livros na estante.")],"Complete: “___ an oven.”",["There is","There are","There be"],0,"Singular: There is."),
30028:("Profissões","Para o trabalho: **I'm an engineer. She's a lawyer.** **What do you do?** = qual é a sua profissão?",[("{{What do you do}}?","O que você faz?"),("{{I'm an}} engineer.","Sou engenheiro."),("{{She's a}} lawyer.","Ela é advogada."),("He's a mechanic.","Ele é mecânico.")],"Como perguntar a profissão?",["What do you do?","What is you job?","Which job you?"],0,"What do you do?"),
70056:("Matérias da escola","Para matérias: **I study math. I like history.** Nomes de línguas e países com **maiúscula**: *English*.",[("I {{study}} science.","Estudo ciências."),("I {{like}} history.","Gosto de história."),("{{English}} is fun.","Inglês é divertido."),("She likes art.","Ela gosta de arte.")],"Qual está certa?",["i like english","I like English.","I like english"],1,"English com maiúscula."),
10169:("How old are you?","Para idade: **How old are you?** — **I'm ten.** (sem *years old* é comum). *I'm ten years old* também vale.",[("{{How old}} are you?","Quantos anos você tem?"),("{{I'm}} nine.","Tenho nove anos."),("{{She's}} twelve years old.","Ela tem doze anos."),("They're twins.","Eles são gêmeos.")],"“Tenho 20 anos”:",["I have 20 years.","I'm 20.","I am 20 old."],1,"I'm 20."),
70057:("Mandar e pedir","Para ordens: **Open the app. Click the link.** O verbo vem sozinho. Negativo: **Don't click.**",[("{{Open}} the app.","Abra o app."),("{{Click}} the link.","Clique no link."),("{{Don't click}} that!","Não clique nisso!"),("Check your battery.","Verifique sua bateria.")],"Como dizer “Não abra”?",["Don't open.","No open.","Not you open."],0,"Don't + verbo."),
30029:("Antônimos","Antônimos úteis: **big ≠ small, heavy ≠ light, loud ≠ quiet, wet ≠ dry.** *The box is heavy, the bag is light.*",[("The box is {{heavy}}.","A caixa é pesada."),("The bag is {{light}}.","A bolsa é leve."),("The room is {{quiet}}.","A sala é silenciosa."),("The towel is {{wet}}.","A toalha está molhada.")],"Oposto de loud:",["quiet","heavy","dry"],0,"Loud ≠ quiet."),
70058:("Always, never, sometimes","Advérbios de frequência vão **antes do verbo**: *I always eat. She never sleeps late.* Mas depois do **be**: *I'm always tired.*",[("I {{always}} eat breakfast.","Sempre tomo café da manhã."),("She {{never}} sleeps late.","Ela nunca dorme tarde."),("We {{sometimes}} walk.","Às vezes caminhamos."),("I'm {{usually}} home at six.","Geralmente estou em casa às seis.")],"Onde vai always?",["antes do verbo","no fim","depois do objeto"],0,"Antes do verbo (depois do be)."),
910014:("Turn on, turn off","**Turn on** = ligar. **Turn off** = desligar. **Turn up** = aumentar. **Turn down** = abaixar. *Turn on the heater.*",[("{{Turn on}} the heater.","Ligue o aquecedor."),("{{Turn off}} the light.","Apague a luz."),("{{Turn up}} the volume.","Aumente o volume."),("{{Turn down}} the music.","Abaixe a música.")],"“Desligar a TV”:",["turn off the TV","turn on the TV","turn up the TV"],0,"Turn off = desligar."),
10170:("Pontos cardeais","**North, south, east, west.** Para direção: **Go north.** *The park is in the west.* Também: **left / right**.",[("{{Go north}}.","Vá para o norte."),("The lake is {{east}}.","O lago fica a leste."),("The sun sets in the {{west}}.","O sol se põe no oeste."),("Use a compass.","Use uma bússola.")],"O que é south?",["sul","norte","leste"],0,"South = sul."),
70059:("Ingredientes e utensílios","Ao cozinhar: **Put the pot on the stove. Add the ingredients.** Imperativo: verbo no começo.",[("{{Put}} the pot on the stove.","Ponha a panela no fogão."),("{{Add}} the ingredients.","Adicione os ingredientes."),("{{Stir}} the sauce.","Mexa o molho."),("Wear an apron.","Use um avental.")],"“Adicione o sal”:",["Add the salt.","You add salt.","Adding salt."],0,"Imperativo."),
30030:("Animais: plural e cor","Animais e cores: **a brown bear, two green snakes.** Cor **antes** do nome. Plural: *monkeys, tigers, giraffes*.",[("A {{brown bear}}.","Um urso marrom."),("Two {{green snakes}}.","Duas cobras verdes."),("The giraffe is tall.","A girafa é alta."),("Dolphins are smart.","Golfinhos são inteligentes.")],"Plural de monkey:",["monkeys","monkies","monkeyes"],0,"Vogal + y: só +s."),
70060:("I can, I can't","**I can** = eu consigo/posso. **I can't** = não consigo. *I can swim. I can't fly.* Depois de **can**, verbo sem -s e sem to.",[("I {{can}} swim.","Eu sei nadar."),("She {{can}} sing.","Ela sabe cantar."),("I {{can't}} fly.","Não sei voar."),("It's my secret power.","É meu poder secreto.")],"Qual está certa?",["She can swims.","She can swim.","She cans swim."],1,"can + verbo base."),
10171:("Passado de be: was, were","Passado de **be**: **I was / he was / she was / it was**; **you were / we were / they were**. *Where were you yesterday?*",[("{{I was}} at home yesterday.","Ontem eu estava em casa."),("{{She was}} tired.","Ela estava cansada."),("{{We were}} at school.","Estávamos na escola."),("{{Where were you}} last night?","Onde você estava ontem à noite?")],"Passado de they are:",["they was","they were","they are"],1,"They were."),
70061:("Passado: what did you do","Passado de verbos regulares: **+ed**: *I walked, I played.* Pergunta: **What did you do?** Depois de **did**, verbo no infinitivo.",[("{{What did you do}} yesterday?","O que você fez ontem?"),("I {{walked}} in the park.","Caminhei no parque."),("She {{played}} guitar.","Ela tocou violão."),("I wrote in my diary.","Escrevi no meu diário.")],"Passado de play:",["played","plaied","plays"],0,"play + ed."),
30031:("Going to: planos","Planos: **I'm going to** + verbo. *I'm going to study.* Ele/ela: **he's going to**.",[("I'm {{going to}} study.","Vou estudar."),("She's {{going to}} travel.","Ela vai viajar."),("We're {{going to}} cook.","Vamos cozinhar."),("What's your plan?","Qual é seu plano?")],"“Vou viajar”:",["I'm going to travel.","I go to travel.","I'm go travel."],0,"be going to + verbo."),
70062:("Would you like…?","Oferecer: **Would you like a sandwich?** Aceitar: **Yes, I'd like one.** Recusar: **No, thanks.**",[("{{Would you like}} some water?","Quer água?"),("{{Yes, please}}.","Sim, por favor."),("{{No, thanks}}.","Não, obrigado."),("Let's make a campfire.","Vamos fazer uma fogueira.")],"Resposta educada a Would you like tea?",["Yes, please.","Yes, I want.","Tea me."],0,"Yes, please."),
910015:("Put on, take off","**Put on** = vestir. **Take off** = tirar. **Hang up** = pendurar. *Put on your socks. Take off your sandals.*",[("{{Put on}} your socks.","Calce as meias."),("{{Take off}} your sandals.","Tire as sandálias."),("{{Hang up}} your vest.","Pendure o colete."),("The mittens are warm.","As luvas são quentinhas.")],"“Tirar os sapatos”:",["take off your shoes","put off shoes","off take shoes"],0,"Take off."),
10172:("What do you think?","Para pedir opinião: **What do you think?** Para dar: **I think…** *I think it's a good idea.*",[("{{What do you think}}?","O que você acha?"),("{{I think}} it's a good idea.","Acho que é uma boa ideia."),("I don't think so.","Acho que não."),("That's a good solution.","É uma boa solução.")],"Como dar uma opinião?",["I think …","I am think …","Me think …"],0,"I think + frase."),
}
